/**
 * "Find medicines" page:
 * https://www.myprime.com/en/medicines.html#find-medicine Flow modeled here:
 * choose a drug list -> search a medicine by name -> pick the autocomplete
 * suggestion -> fill in strength/quantity/frequency -> submit, which renders a
 * result card showing dose info and formulary/drug-list status.
 */
import { BasePage, exactTextCi } from './base-page.js';
import { MedicineDetailsPage } from './medicine-details-page.js';

export class MedicineSearchPage extends BasePage {
  /** @param {import('@playwright/test').Page} page */
  constructor(page) {
    super(page);
    // .first(): Selenium By-locators resolve to the first match; the AUT even
    // ships duplicate ids, so keep that semantic instead of strict mode.
    this.healthPlanText = page.locator("#selectedYearHealthPlanText").first();
    this.drugListDropdown = page.locator("#new-drug-list-selector").first();
    this.drugListApplyButton = page.locator("#drug-list-selector-button").first();
    this.searchInput = page.locator("#medicine-search-query").first();
    this.strengthDropdown = page.locator("#medicine-search-form-strength").first();
    this.quantityInput = page.locator("#medicine-search-form-quantity").first();
    this.frequencyDropdown = page.locator("#medicine-search-form-frequency").first();
    this.submitAddMedicine = page.locator("#medicine-search-form-submit").first();
    this.signInNagDismiss = page.locator("#prelogin-planselector-button").first();
  }

  async open() {
    await this.page.goto("/en/medicines.html#find-medicine");
    await this.searchInput.waitFor({ state: 'visible' });
    await this.dismissSignInNagIfPresent();
    return this;
  }

  /**
   * Best-effort dismissal of the sign-in nag described above. Safe to call
   * defensively before any keyboard-driven interaction on this page.
   */
  async dismissSignInNagIfPresent() {
    if (await this.isVisibleWithin(this.signInNagDismiss, 4000)) {
      await this.signInNagDismiss.click();
    }
  }

  /**
   * Reads the "Your health plan: X" banner and returns just the plan name.
   */
  async getSelectedHealthPlan() {
    const fullText = await this.readText(this.healthPlanText);
    return fullText.replace("Your health plan:", "").trim();
  }

  async selectDrugList(drugListName) {
    await this.selectOptionWhenPopulated(this.drugListDropdown, drugListName);
    await this.drugListApplyButton.click();
    return this;
  }

  async searchAndSelectMedicine(searchTerm, exactSuggestionText) {
    // Suggestion label case differs between DOM, CSS rendering, and oracle
    // data, so match the whole label case-insensitively (legacy parity).
    const suggestion = this.page
      .locator('a.result-row')
      .filter({ hasText: exactTextCi(exactSuggestionText) });
    let lastError = null;
    for (let attempt = 1; attempt <= 3; attempt++) {
      await this.dismissSignInNagIfPresent();
      // The widget only reacts to real key events, and can miss the first
      // keystroke burst right after page load; clear and retype to recover.
      await this.searchInput.fill('');
      await this.searchInput.pressSequentially(searchTerm, { delay: 50 });
      try {
        await suggestion.first().click({ timeout: 6000 });
        return this;
      } catch (e) {
        lastError = e;
      }
    }
    throw lastError;
  }

  async selectStrength(strengthText) {
    await this.selectOptionWhenPopulated(this.strengthDropdown, strengthText);
    return this;
  }

  async setQuantity(quantity) {
    await this.quantityInput.fill(quantity);
    return this;
  }

  async selectFrequency(frequencyText) {
    await this.selectOptionWhenPopulated(this.frequencyDropdown, frequencyText);
    return this;
  }

  async submitAddMedicineForm() {
    await this.submitAddMedicine.click();
    return this;
  }

  /**
   * Full "add a medicine" flow in one call: search, pick suggestion, set
   * strength/quantity/frequency, submit. Renders a result card for the drug.
   */
  async addMedicine(searchTerm, exactSuggestionText, strengthText, quantity, frequencyText) {
    await this.searchAndSelectMedicine(searchTerm, exactSuggestionText);
    await this.selectStrength(strengthText);
    await this.setQuantity(quantity);
    await this.selectFrequency(frequencyText);
    return await this.submitAddMedicineForm();
  }

  resultCard(exactDrugName) {
    return this.page
      .locator('.medicine-information-container')
      .filter({ has: this.page.locator('a.medicine-name', { hasText: exactTextCi(exactDrugName) }) });
  }

  /**
   * e.g. "Not on drug list, Non-formulary" or "On drug list, Tier 1/Preferred
   * Generic".
   */
  async getCardFormularyText(exactDrugName) {
    const card = this.resultCard(exactDrugName);
    return (await card.locator("p.covered-on-drug-list").first().textContent()).trim();
  }

  /**
   * e.g. "10mg tablet / 30 tablets over 30 days".
   */
  async getCardDoseInfo(exactDrugName) {
    const card = this.resultCard(exactDrugName);
    return (await card.locator("span[id*=\"find-med-dfs\"]").first().textContent()).trim();
  }

  async openMedicineDetails(exactDrugName) {
    const card = this.resultCard(exactDrugName);
    await card.locator("a.medicine-name").first().click();
    const medicineDetailsPage = new MedicineDetailsPage(this.page);
    await medicineDetailsPage.waitForLoaded();
    return medicineDetailsPage;
  }
}
